# PATCH v1.3.4: санитайзер дерева «Проверка -> Гипотезы -> Задания».
# Принимает ОБА формата:
#   (A) плоский массив — [{kind:'hypothesis',...}, {kind:'task',parent,...}]
#       (так отправлял tracker.js v1.3.2)
#   (B) дерево — [{kind:'hypothesis', tasks:[{kind:'task',...}]}]
#       (так отправляет tracker.js v1.3.4+)
# РАНЬШЕ разбирался только (B), поэтому задачи из (A) верхнего уровня
# безусловно превращались в гипотезы — parent терялся, и «задание
# переезжало к следующей гипотезе».
def _clean_hyp_tree(raw, valid_emps):
    import re as _re_h
    out = []
    used_ids = set()
    if not isinstance(raw, list):
        return out
    def _uniq(hid, title):
        base = hid
        n = 2
        while hid in used_ids:
            hid = f'{base}_{n}'
            n += 1
        used_ids.add(hid)
        return hid
    def _mk(item, kind, parent_no):
        title = str(item.get('title', '') if isinstance(item, dict) else '').strip()[:200]
        if not title:
            return None
        desc = str(item.get('description', '') if isinstance(item, dict) else '').strip()[:4000]
        d_from = str(item.get('date_from', '') if isinstance(item, dict) else '').strip()[:10]
        d_to = str(item.get('date_to', '') if isinstance(item, dict) else '').strip()[:10]
        if d_from and not _valid_date(d_from):
            d_from = ''
        if d_to and not _valid_date(d_to):
            d_to = ''
        st = str(item.get('status', '') if isinstance(item, dict) else '').strip().lower()[:10]
        if st not in ('planned', 'in_progress', 'done', 'failed'):
            st = 'planned'
        _asg = item.get('assignees') if isinstance(item, dict) else []
        if not isinstance(_asg, list):
            _asg = []
        asg = []
        for a in _asg[:50]:
            a = str(a).strip()
            if a and a in valid_emps and a not in asg:
                asg.append(a)
        hid = str(item.get('id', '') if isinstance(item, dict) else '').strip()[:64]
        if not hid or not _re_h.match(r'^[A-Za-z0-9_-]+$', hid):
            hid = 'h' + format(abs(hash(title + str(len(out)))) % 10**12, 'x')
        hid = _uniq(hid, title)
        return {'id': hid, 'kind': kind, 'parent': parent_no, 'no': len(out) + 1,
                'title': title, 'description': desc, 'date_from': d_from,
                'date_to': d_to, 'status': st, 'assignees': asg}
    # Определяем формат: если среди элементов ВЕРХНЕГО уровня есть
    # хотя бы один с kind='task' — это плоский массив (вариант A).
    is_flat = False
    for _x in raw[:100]:
        if isinstance(_x, dict) and str(_x.get('kind', '')).strip() == 'task':
            is_flat = True
            break
    if is_flat:
        # Ветка A: плоский массив. Сначала все гипотезы (строим карту
        # orig_id -> new_id на случай переименования при _uniq), затем
        # задачи с пересчитанным parent.
        hyp_map = {}
        for item in raw[:200]:
            if not isinstance(item, dict):
                continue
            if str(item.get('kind', '')).strip() != 'hypothesis':
                continue
            hh = _mk(item, 'hypothesis', '')
            if not hh:
                continue
            out.append(hh)
            _orig = str(item.get('id', '')).strip()
            if _orig:
                hyp_map[_orig] = hh['id']
        for item in raw[:200]:
            if not isinstance(item, dict):
                continue
            if str(item.get('kind', '')).strip() != 'task':
                continue
            _op = str(item.get('parent', '')).strip()
            _np = hyp_map.get(_op, '')
            if not _np:
                continue  # сирота — привязывать некуда
            tt = _mk(item, 'task', _np)
            if tt:
                out.append(tt)
        return out
    # Ветка B: дерево — гипотезы верхнего уровня, задачи внутри .tasks.
    for h in raw[:100]:
        hh = _mk(h, 'hypothesis', '')
        if not hh:
            continue
        out.append(hh)
        children = h.get('tasks') if isinstance(h, dict) else []
        if not isinstance(children, list):
            children = []
        for tk in children[:100]:
            tt = _mk(tk, 'task', hh['id'])
            if tt:
                out.append(tt)
    return out

// PATCH v1.3.4: преобразуем плоский массив в ДЕРЕВО перед отправкой.
// Старая версия (v1.3.2) слала плоский массив, а бэкенд v1.3.2
// разворачивал каждый top-level элемент как гипотезу — задачи
// теряли parent и превращались в новые гипотезы.
hypotheses: (function(){
    var _flat = (window.__trkHypDraft || []).slice();
    var _hyps = _flat.filter(function(x){ return x && x.kind === 'hypothesis'; });
    return _hyps.map(function(h){
        var item = Object.assign({}, h);
        item.tasks = _flat.filter(function(x){
            return x && x.kind === 'task' && x.parent === h.id;
        });
        return item;
    });
})(),

