// PATCH v1.3.4: гарантированная подгрузка сотрудников. Раньше при
// первом открытии карточки (или после F5, когда loadState ещё не
// завершился) window.__trkState.employees мог быть пуст — peopleHtml
// возвращал «Список сотрудников пуст», и чекбоксы не рисовались.
var _renderTreeAfter = function(){
    var _hb2 = document.getElementById('hypCountBadge');
    if (_hb2) _hb2.textContent = _hm.length + ' гип., ' + _nm.filter(function(x){return x && x.kind === 'task';}).length + ' зад.';
    if (typeof window.__renderHypTree === 'function') window.__renderHypTree();
    else if (typeof renderHypTree === 'function') renderHypTree();
};
var _stV134 = window.__trkState || {};
if (_stV134.employees && _stV134.employees.length) {
    _renderTreeAfter();
} else {
    var _rootV134 = document.getElementById('hypTreeRoot');
    if (_rootV134) _rootV134.innerHTML = '<div class="hyp-empty">Загрузка сотрудников…</div>';
    fetch('/api/tracker/state', {credentials: 'same-origin', cache: 'no-store'})
        .then(function(r){ return r.json(); })
        .then(function(d){
            if (d && d.success && window.__trkState) {
                if (d.employees) window.__trkState.employees = d.employees;
                if (d.tasks) window.__trkState.tasks = d.tasks;
                if (d.departments) window.__trkState.departments = d.departments;
                if (d.teams) window.__trkState.teams = d.teams;
            }
            _renderTreeAfter();
        })
        .catch(function(){ _renderTreeAfter(); });
}

/* ============================================================
   PATCH v1.3.4 — гарантированное растягивание дерева гипотез
   на всю ширину карточки задачи.

   Старый код (v1.1.3-final-fix) искал несуществующий #hypTreeGroup;
   реальный id — #taskHypothesesGroup. Здесь мы переносим группу
   из .task-modal-grid (где она оказывается в одной колонке) в
   .task-modal-scroll сразу ПОСЛЕ grid — так она занимает обе
   колонки по ширине модалки.

   Проверка: group.parentNode !== grid.parentNode (а не === grid) —
   потому что при реструктуризации группа попадает в
   .task-modal-col-main (дочерний узел grid), а не в сам grid.
   ============================================================ */
(function(){
    'use strict';
    if (window.__trkHypFullWidthV134) return;
    window.__trkHypFullWidthV134 = true;

    function _moveHypGroup(){
        var modal = document.getElementById('taskModal');
        if (!modal || !modal.classList.contains('active')) return;
        var group = document.getElementById('taskHypothesesGroup');
        if (!group) return;
        var scroll = modal.querySelector('.modal-content > .task-modal-scroll')
                  || modal.querySelector('.modal-content');
        var grid = modal.querySelector('.task-modal-grid');
        if (!scroll) return;
        if (grid && group.parentNode !== grid.parentNode) {
            grid.parentNode.insertBefore(group, grid.nextSibling);
        }
        group.style.setProperty('width', '100%', 'important');
        group.style.setProperty('max-width', '100%', 'important');
        group.style.setProperty('box-sizing', 'border-box', 'important');
        group.style.setProperty('align-self', 'stretch', 'important');
        group.classList.add('trk-hyp-fullwidth-v134');
    }

    function _watchTaskModal(){
        var modal = document.getElementById('taskModal');
        if (!modal || modal._hypFullWidthV134Obs) return;
        modal._hypFullWidthV134Obs = true;
        new MutationObserver(function(){
            if (modal.classList.contains('active')) {
                setTimeout(_moveHypGroup, 60);
                setTimeout(_moveHypGroup, 200);
                setTimeout(_moveHypGroup, 500);
            }
        }).observe(modal, { attributes: true, attributeFilter: ['class'] });
    }

    _watchTaskModal();
    setTimeout(_watchTaskModal, 500);
    setTimeout(_watchTaskModal, 1500);
    setTimeout(_watchTaskModal, 3000);

    document.addEventListener('click', function(e){
        if (!e.target || !e.target.closest) return;
        if (e.target.closest('#addTaskBtn') ||
            e.target.closest('#addTaskBtn2') ||
            e.target.closest('.task-card-clickable') ||
            e.target.closest('[data-act="edit"]')) {
            setTimeout(_moveHypGroup, 200);
            setTimeout(_moveHypGroup, 500);
        }
    }, true);

    window.__trkMoveHypGroupV134 = _moveHypGroup;
})();

